export interface MCPServer {
  slug: string;
  name: string;
  description: string;
  author: string;
  /**
   * Repository URL, or null when no real repository could be confirmed.
   * Null is deliberate and load-bearing: the catalog previously carried
   * thousands of github_url values that 404'd, and anything presented as a
   * link has to be one the GitHub API confirmed. See `verification`.
   */
  github_url: string | null;
  /** True only if github_url was confirmed to resolve against the live GitHub API. */
  source_verified?: boolean;
  /**
   * live       — repo confirmed to exist and be active
   * archived   — repo exists but is archived (link works, project is not maintained)
   * unresolved — no real repository found; github_url is null. Trust scoring
   *              must exclude these rather than score a repo that isn't there.
   */
  verification?: 'live' | 'archived' | 'unresolved';
  website_url?: string;
  categories: string[];
  integrations: string[];
  install_type: 'npm' | 'pip' | 'binary' | 'docker' | 'source' | 'remote';
  install_command?: string;
  /**
   * Whether install_command's artifact was confirmed to exist on install_checked:
   * npm / PyPI for package installs, and — since 2026-08-01 — the container
   * registry for `docker` installs and the release page for `binary` ones.
   * False means the lookup 404'd; the command is kept for reference but must
   * never be presented as a working copy-paste. Same principle as
   * `source_verified` for github_url. See `registryLabel()` for the user-facing
   * name of the place that was checked.
   */
  install_verified?: boolean;
  /** ISO date the registry check behind install_verified was run. */
  install_checked?: string;
  featured?: boolean;
  /** Paid sponsored placement — renders in homepage sponsored strip with gold accent */
  sponsored?: boolean;
  official?: boolean;
  stars?: number;
  isNew?: boolean;
}

export interface Category {
  slug: string;
  name: string;
  description: string;
  emoji: string;
  count?: number;
}

export interface Integration {
  slug: string;
  name: string;
  description: string;
  icon: string;
  count?: number;
}

/**
 * Where an install_command's artifact lives, for the verified / unverified copy
 * on server and pricing pages. This started as an npm-vs-PyPI ternary inlined in
 * four places, which silently mislabelled every `docker` and `binary` entry as
 * npm the moment those install types started carrying install_verified.
 */
export function registryLabel(installType: MCPServer['install_type']): string {
  switch (installType) {
    case 'pip':
      return 'PyPI';
    case 'npm':
      return 'the npm registry';
    case 'docker':
      return 'the container registry';
    case 'binary':
      return 'the project release page';
    // A hosted server has no artifact to publish; the verified/unverified copy
    // should never render for one, but label it honestly if it ever does.
    case 'remote':
      return 'no registry (this server is hosted)';
    default:
      return 'its registry';
  }
}

